SELECT 'payment_detail→payment_header' AS rel, COUNT(*) AS huerfanos FROM tenant_finance.payment_detail pd LEFT JOIN tenant_finance.payment_header ph ON pd.payment_header_uuid=ph.payment_header_uuid WHERE pd.payment_header_uuid IS NOT NULL AND ph.payment_header_uuid IS NULL
UNION ALL SELECT 'rebate→stamped_rebate (by doc#)', COUNT(*) FROM tenant_finance.rebate r LEFT JOIN tenant_finance.stamped_rebate sr ON r.document_number=sr.document_number WHERE r.document_number IS NOT NULL AND sr.document_number IS NULL
UNION ALL SELECT 'reception→purchase_order', COUNT(*) FROM tenant_finance.reception r LEFT JOIN tenant_finance.purchase_order po ON r.purchase_order_uuid=po.purchase_order_uuid WHERE r.purchase_order_uuid IS NOT NULL AND po.purchase_order_uuid IS NULL
UNION ALL SELECT 'reception_sku→reception', COUNT(*) FROM tenant_finance.reception_sku rs LEFT JOIN tenant_finance.reception r ON rs.reception_id=r.reception_id WHERE rs.reception_id IS NOT NULL AND r.reception_id IS NULL
UNION ALL SELECT 'shipping_guide_document→shipping_guide', COUNT(*) FROM tenant_finance.shipping_guide_document sgd LEFT JOIN tenant_finance.shipping_guide sg ON sgd.shipping_guide_id=sg.shipping_guide_id WHERE sgd.shipping_guide_id IS NOT NULL AND sg.shipping_guide_id IS NULL
UNION ALL SELECT 'sg_po→shipping_guide', COUNT(*) FROM tenant_finance.shipping_guide_purchase_order sgpo LEFT JOIN tenant_finance.shipping_guide sg ON sgpo.shipping_guide_id=sg.shipping_guide_id WHERE sgpo.shipping_guide_id IS NOT NULL AND sg.shipping_guide_id IS NULL
UNION ALL SELECT 'sg_po→purchase_order', COUNT(*) FROM tenant_finance.shipping_guide_purchase_order sgpo LEFT JOIN tenant_finance.purchase_order po ON sgpo.purchase_order_uuid=po.purchase_order_uuid WHERE sgpo.purchase_order_uuid IS NOT NULL AND po.purchase_order_uuid IS NULL
UNION ALL SELECT 'twm_logs→twm_ejecucion', COUNT(*) FROM tenant_finance.twm_logs tl LEFT JOIN tenant_finance.twm_ejecucion te ON tl.id_ejecucion=te.id WHERE tl.id_ejecucion IS NOT NULL AND te.id IS NULL
UNION ALL SELECT 'twm_cifras_control→twm_ejecucion', COUNT(*) FROM tenant_finance.twm_cifras_control tcc LEFT JOIN tenant_finance.twm_ejecucion te ON tcc.id_ejecucion=te.id WHERE tcc.id_ejecucion IS NOT NULL AND te.id IS NULL
UNION ALL SELECT 'account_statement→previous_statement', COUNT(*) FROM tenant_finance.account_statement a LEFT JOIN tenant_finance.account_statement b ON a.previous_statement_uuid=b.account_statement_uuid WHERE a.previous_statement_uuid IS NOT NULL AND b.account_statement_uuid IS NULL
UNION ALL SELECT 'as_invoice→account_statement', COUNT(*) FROM tenant_finance.account_statement_invoice asi LEFT JOIN tenant_finance.account_statement a ON asi.account_statement_uuid=a.account_statement_uuid WHERE asi.account_statement_uuid IS NOT NULL AND a.account_statement_uuid IS NULL
UNION ALL SELECT 'as_credit_note→account_statement', COUNT(*) FROM tenant_finance.account_statement_credit_note ascn LEFT JOIN tenant_finance.account_statement a ON ascn.account_statement_uuid=a.account_statement_uuid WHERE ascn.account_statement_uuid IS NOT NULL AND a.account_statement_uuid IS NULL
UNION ALL SELECT 'as_discount→account_statement', COUNT(*) FROM tenant_finance.account_statement_discount asd LEFT JOIN tenant_finance.account_statement a ON asd.account_statement_uuid=a.account_statement_uuid WHERE asd.account_statement_uuid IS NOT NULL AND a.account_statement_uuid IS NULL
UNION ALL SELECT 'as_payment→account_statement', COUNT(*) FROM tenant_finance.account_statement_payment asp LEFT JOIN tenant_finance.account_statement a ON asp.account_statement_uuid=a.account_statement_uuid WHERE asp.account_statement_uuid IS NOT NULL AND a.account_statement_uuid IS NULL
UNION ALL SELECT 'as_purchase_order→account_statement', COUNT(*) FROM tenant_finance.account_statement_purchase_order aspo LEFT JOIN tenant_finance.account_statement a ON aspo.account_statement_uuid=a.account_statement_uuid WHERE aspo.account_statement_uuid IS NOT NULL AND a.account_statement_uuid IS NULL
UNION ALL SELECT 'as_reception→account_statement', COUNT(*) FROM tenant_finance.account_statement_reception asr LEFT JOIN tenant_finance.account_statement a ON asr.account_statement_uuid=a.account_statement_uuid WHERE asr.account_statement_uuid IS NOT NULL AND a.account_statement_uuid IS NULL
UNION ALL SELECT 'version_catalog→pac (fin)', COUNT(*) FROM tenant_finance.version_catalog vc LEFT JOIN tenant_finance.pac_catalog pc ON vc.pac_id=pc.pac_id WHERE vc.pac_id IS NOT NULL AND pc.pac_id IS NULL
UNION ALL SELECT 'stamped_rebate→fiscal.invoice', COUNT(*) FROM tenant_finance.stamped_rebate sr LEFT JOIN tenant_fiscal.invoice i ON sr.invoice_fiscal_uuid=i.fiscal_uuid WHERE sr.invoice_fiscal_uuid IS NOT NULL AND i.fiscal_uuid IS NULL
UNION ALL SELECT 'addendum_manual→fiscal.invoice', COUNT(*) FROM tenant_finance.addendum_manual am LEFT JOIN tenant_fiscal.invoice i ON am.invoice_uuid=i.invoice_uuid WHERE am.invoice_uuid IS NOT NULL AND i.invoice_uuid IS NULL
UNION ALL SELECT 'addendum_manual→reception', COUNT(*) FROM tenant_finance.addendum_manual am LEFT JOIN tenant_finance.reception r ON am.reception_id=r.reception_id WHERE am.reception_id IS NOT NULL AND r.reception_id IS NULL
ORDER BY 2 DESC;
